<?php $archived = $page === 'records' && ($_GET['archived'] ?? '') === '1'; $rows = filteredRecords($archived); $compact = false; ?>
<div class="page-heading no-print"><div><div class="eyebrow"><?= $page === 'reports' ? 'COMMUNITY INSIGHTS' : 'YOUTH DIRECTORY' ?></div><h1><?= e($title) ?></h1><p><?= ['records' => 'One place for your community’s youth information.', 'idcards' => 'Select a registered youth to preview and print their ID card.', 'reports' => 'Filter and print your community’s OSY master list.'][$page] ?></p></div><?php if ($page === 'reports'): ?><button class="button primary" data-print><?= icon('print') ?> Print report</button><?php else: ?><a class="button primary" href="<?= e(url('register')) ?>"><span class="plus">+</span> Register OSY</a><?php endif; ?></div>
<?php if ($page === 'reports'): ?><div class="print-only report-header"><h1>Out-of-School Youth Master List</h1><p><?= e($config['organization']) ?> · Generated <?= date('F j, Y, g:i a') ?></p><p>Filters: <?= e(implode(' · ', array_filter([$_GET['q'] ?? '', $_GET['sex'] ?? '', $_GET['status'] ?? '', $_GET['employment_status'] ?? ''])) ?: 'All registered OSY') ?></p></div><?php endif; ?>
<?php if ($page === 'records'): ?><div class="tabs no-print"><a class="<?= !$archived ? 'active-tab' : '' ?>" href="<?= e(url('records')) ?>">Registered youth</a><a class="<?= $archived ? 'active-tab' : '' ?>" href="<?= e(url('records', ['archived' => 1])) ?>">Archived records</a></div><?php endif; ?>
<section class="panel"><form class="filters no-print" method="get"><input type="hidden" name="page" value="<?= e($page) ?>"><?php if ($archived): ?><input type="hidden" name="archived" value="1"><?php endif; ?><div class="search-input"><?= icon('search') ?><input aria-label="Search by name or OSY ID" name="q" placeholder="Search by name or OSY ID…" value="<?= e($_GET['q'] ?? '') ?>"></div>
<?php foreach (['sex' => ['All sexes', 'Male', 'Female'], 'status' => ['All statuses', 'Active', 'Inactive'], 'employment_status' => ['All employment', 'Employed', 'Unemployed']] as $key => $options): ?><select name="<?= e($key) ?>" aria-label="<?= e($options[0]) ?>"><?php foreach ($options as $i => $option): ?><option value="<?= $i ? e($option) : '' ?>" <?= ($_GET[$key] ?? '') === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select><?php endforeach; ?><button class="button secondary" type="submit">Apply</button><a class="reset-link" href="<?= e(url($page, $archived ? ['archived' => 1] : [])) ?>">Reset</a></form><div class="list-summary"><strong><?= $archived ? 'Archived records' : ($page === 'reports' ? 'OSY master list' : 'Registered youth') ?></strong><span><?= count($rows) ?> <?= count($rows) === 1 ? 'record' : 'records' ?></span></div><?php require __DIR__ . '/table.php'; ?></section><p class="table-footnote"><?= $archived ? 'Archived records are kept for reference and can be restored from their profile.' : 'Archived records are excluded from this list and dashboard totals.' ?></p>
